"""
import_service – Stellt die Funktion import_table() bereit, um CSV-Dateien in die Datenbank zu importieren.

Verwendung:
    from core_services.db import get_query_text, execute_sql_query, update_last_updated, status_table, prozedur_db
    get_column_mapping - Holt die Spaltenzuordnung für das gegebene Datenbank-Schema.
    get_update_exclusion_fields - Holt die Felder, die bei einem UPDATE ausgeschlossen werden sollen
    batch_insert - Führt eine Batch-Einfügung (INSERT ... ON DUPLICATE KEY UPDATE) durch.
    import_table - Importiert eine CSV-datei in die angegebene tabelle der Datenbank
    handle_import - Verarbeitet den Import von Daten.
    import_table_with_temp - Importiert eine CSV-datei in die angegebene tabelle der
    Datenbank unter Verwendung einer temporären tabelle.
    rechnungsemail - Importiert die Rechnungsemail aus einer CSV-datei in die
    Datenbank.
    ivw - Funktion zur Bereinigung der IVW-Daten in der tabelle tb_ivw_grundlage
    lieferbarkeiten_csv_verarbeiten - Konvertiert Lieferbarkeitsdateien nach UTF-8 mit BOM.
    importiere_dateien - Importiert konfigurierte Dateien und verschiebt sie bei Erfolg.
"""

import logging
import math
import re
import tempfile
from collections.abc import Callable
from datetime import datetime
from pathlib import Path
from typing import Any

import mariadb
import pandas as pd

from ..constants import DATABASE, TIMEZONE
from ..utils.convert_utils import csv_zu_utf8_bom
from ..utils.progress_logging import iter_with_progress
from .client import DbCredentials, connect_to_db
from .db_service import execute_dataframe_query, execute_sql_query, get_query_text, prozedur_db, update_last_updated

logger = logging.getLogger(__name__)


FileImportFunc = Callable[[str], bool]
PostProcessFunc = Callable[[], None]
FileImportConfig = tuple[str, FileImportFunc, PostProcessFunc | None]
ImportErgebnis = tuple[frozenset[str], bool]


def lieferbarkeiten_csv_verarbeiten(filepath: str | Path) -> str:
    """Konvertiert eine Lieferbarkeitsdatei atomar nach UTF-8 mit BOM.

    Args:
        filepath: Pfad der zu verarbeitenden Lieferbarkeitsdatei.

    Returns:
        Die erkannte Zeichenkodierung der Quelldatei.
    """
    datei_pfad = Path(filepath)

    with tempfile.NamedTemporaryFile(
        suffix=".csv",
        delete=False,
        dir=datei_pfad.parent,
    ) as temp:
        ausgabe_pfad = Path(temp.name)

    try:
        codierung = csv_zu_utf8_bom(datei_pfad, ausgabe_pfad)
        ausgabe_pfad.replace(datei_pfad)
        return codierung
    finally:
        ausgabe_pfad.unlink(missing_ok=True)


def importiere_dateien(
    import_configs: list[FileImportConfig],
    eingabe_ordner: str | Path,
    ziel_ordner: str | Path,
) -> ImportErgebnis:
    """Fuehrt Import, Nachverarbeitung und Verschieben aus."""
    eingabe_pfad = Path(eingabe_ordner)
    ziel_pfad = Path(ziel_ordner)
    dateinamen = [datei.name for datei in eingabe_pfad.iterdir() if datei.is_file()]
    logger.info("Gefundene Dateien: %s", dateinamen)

    erfolgreiche_praefixe: set[str] = set()
    erfolgreich = True
    for praefix, import_func, post_func in iter_with_progress(
        logger,
        import_configs,
        len(import_configs),
        "Import-Praefixe",
    ):
        passende_dateien = sorted(dateiname for dateiname in dateinamen if dateiname.startswith(praefix))
        logger.info(
            "Verarbeite Praefix '%s' (%s Datei(en)): %s",
            praefix,
            len(passende_dateien),
            passende_dateien,
        )
        for dateiname in iter_with_progress(
            logger,
            passende_dateien,
            len(passende_dateien),
            f"Dateien fuer {praefix}",
        ):
            quelldatei = eingabe_pfad / dateiname
            try:
                verarbeitet = import_func(str(quelldatei))
            except Exception:
                logger.exception("Fehler beim Verarbeiten von %s", dateiname)
                raise

            if not verarbeitet:
                logger.warning("Datei %s nicht verschoben - Verarbeitung nicht erfolgreich", dateiname)
                erfolgreich = False
                continue

            try:
                quelldatei.rename(ziel_pfad / dateiname)
            except OSError:
                logger.exception("Fehler beim Verschieben von %s", dateiname)
                raise
            logger.info("Datei %s erfolgreich verschoben", dateiname)
            erfolgreiche_praefixe.add(praefix)

        if post_func and passende_dateien:
            try:
                post_func()
            except Exception:
                logger.exception("Fehler bei der Nachverarbeitung nach '%s'", praefix)
                raise

    return frozenset(erfolgreiche_praefixe), erfolgreich


def get_column_mapping(database: str = DATABASE, db_credentials: DbCredentials | None = None) -> dict[str, str]:
    """Holt die Spaltenzuordnung für das gegebene Datenbank-Schema.

    Args:
        database: Der Name der Datenbank.
        db_credentials: Optionale direkte DB-Zugangsdaten.

    Returns:
        Ein Dictionary mit der Spaltenzuordnung im Format {csv_column: db_column}.
        Leeres Dictionary bei Fehler.
    """

    connection = None
    try:
        connection = connect_to_db(database, credentials=db_credentials)
        cursor = connection.cursor(dictionary=True)
        cursor.execute("SELECT csv_column, db_column FROM tb_column_mapping")
        rows = cursor.fetchall()
        column_mapping = {row["csv_column"]: row["db_column"] for row in rows}
        cursor.close()
        return column_mapping
    except mariadb.Error as e:
        logger.error(f"Fehler beim Abrufen der Spaltenzuordnung: {e}", exc_info=True)
        raise
    finally:
        if connection:
            connection.close()


def get_update_exclusion_fields(
    table_name: str, database: str = DATABASE, db_credentials: DbCredentials | None = None
) -> list[str]:
    """Holt die Felder, die bei einem UPDATE ausgeschlossen werden sollen.

    Args:
        table_name: Der Name der Import-tabelle.
        database: Der Name der Datenbank.
        db_credentials: Optionale direkte DB-Zugangsdaten.

    Returns:
        Eine Liste der ausgeschlossenen Feldnamen. Leere Liste bei Fehler.
    """

    connection = None
    try:
        connection = connect_to_db(database, credentials=db_credentials)
        cursor = connection.cursor()
        cursor.execute("SELECT field FROM tb_update_exclusions WHERE import_table = %s", (table_name,))
        rows = cursor.fetchall()
        excluded_fields = [row[0] for row in rows] if rows else []
        cursor.close()
        return excluded_fields
    except Exception as e:
        logger.error(f"Fehler beim Abrufen der Exclusion Fields: {e}", exc_info=True)
        raise
    finally:
        if connection:
            connection.close()


def _validate_identifier(name: str) -> str:
    """Prüft ob ein SQL-Bezeichner (tabelle/Spalte) sicher ist und gibt ihn mit Backticks zurück.

    Args:
        name: Der zu validierende Bezeichner.

    Returns:
        Den Bezeichner in Backticks escaped.

    Raises:
        ValueError: Wenn der Bezeichner ungültige Zeichen enthält.
    """
    if not re.match(r"^[a-zA-Z0-9_]+$", name):
        raise ValueError(f"Ungültiger SQL-Bezeichner: {name}")
    return f"`{name}`"


def _safe_rollback(connection: Any) -> None:
    """Versucht einen Datenbank-Rollback und loggt Fehler beim Rollback.

    Args:
        connection: Die MariaDB-Verbindung.
    """
    if not connection:
        return

    try:
        connection.rollback()
    except mariadb.Error as rollback_error:
        logger.error(f"Fehler beim Rollback der Datenbanktransaktion: {rollback_error}", exc_info=True)


def batch_insert(
    cursor: Any, df: pd.DataFrame, table: str, excluded_fields: list[str], truncate_table: str = "Ja"
) -> None:
    """Führt eine Batch-Einfügung (INSERT ... ON DUPLICATE KEY UPDATE) durch.

    Args:
        cursor: Ein MariaDB-Cursor-Objekt.
        df: Ein Pandas DataFrame mit den einzufügenden Daten.
        table: Der Name der Zieltabelle.
        excluded_fields: Felder, die beim ON DUPLICATE KEY UPDATE übersprungen werden.
        truncate_table: 'Ja' um die tabelle vorher zu leeren, 'Nein' um Daten anzuhängen.
    """
    safe_table = _validate_identifier(table)
    safe_columns = [_validate_identifier(col) for col in df.columns]

    if truncate_table == "Ja":
        cursor.execute(f"TRUNCATE TABLE {safe_table}")
    columns = ", ".join(safe_columns)
    placeholders = ", ".join([f"%({col})s" for col in df.columns])
    update_clause = ", ".join(
        [
            f"{_validate_identifier(col)} = VALUES({_validate_identifier(col)})"
            for col in df.columns
            if col not in excluded_fields
        ]
    )
    query = f"""
        INSERT INTO {safe_table} ({columns})
        VALUES ({placeholders})
        ON DUPLICATE KEY UPDATE {update_clause}
    """
    batch_size = 10000
    num_batches = math.ceil(len(df) / batch_size)
    for batch_num in iter_with_progress(logger, range(num_batches), num_batches, f"Batch-Import in {table}"):
        batch_df = df.iloc[batch_num * batch_size : (batch_num + 1) * batch_size]
        params_list = [{k: (None if pd.isna(v) else v) for k, v in row.items()} for _, row in batch_df.iterrows()]
        cursor.executemany(query, params_list)


def import_table(
    csv_file_path: str,
    target_table: str,
    truncate_table: str = "Ja",
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
    seperator: str = ",",
    **kwargs: Any,
) -> bool:
    """Importiert eine CSV-datei in die angegebene tabelle der Datenbank."""
    logger.info(f"Importiere datei: {csv_file_path} in tabelle: {target_table}")
    df = pd.read_csv(csv_file_path, dtype=str, keep_default_na=False, sep=seperator)
    if df.empty:
        logger.info(f"CSV-datei enthält keine Daten (nur Überschriften), Import wird übersprungen: {csv_file_path}")
        return True
    result = save_df_to_db(df, target_table, truncate_table, database, db_credentials=db_credentials)
    if result:
        logger.info(f"{csv_file_path} erfolgreich in {target_table} importiert.")
    return result


def handle_import(import_func: Callable[..., Any], *args: Any, **kwargs: Any) -> bool:
    """Verarbeitet den Import von Daten.

    Args:
        import_func (Callable): Die Importfunktion, die aufgerufen werden soll.
        *args: Argumente für die Importfunktion.
        **kwargs: Schlüsselwortargumente für die Importfunktion.
    Returns:
        bool: True bei Erfolg, False bei Fehler
    """

    try:
        result = import_func(*args, **kwargs)
        success = result is True or result == "Success"
        if success:
            logger.info(f"Import erfolgreich: {args[0] if args else ''}")
        else:
            logger.warning(f"Import nicht erfolgreich (Rückgabewert: {result}): {args[0] if args else ''}")
        return success
    except Exception as e:
        logger.error(f"Fehler beim Importieren: {args[0] if args else ''}: {e}", exc_info=True)
        return False


def import_table_with_temp(
    csv_file_path: str,
    target_table: str,
    prozedur: str,
    create_table_query: str,
    database: str = DATABASE,
    db_credentials: DbCredentials | None = None,
) -> bool:
    """Importiert eine CSV-datei unter Verwendung einer temporären tabelle.

    Erstellt eine temporäre tabelle, fügt die CSV-Daten ein, führt die
    angegebene Stored Procedure aus und löscht die temporäre tabelle.

    Args:
        csv_file_path: Der Pfad zur CSV-datei, die importiert werden soll.
        target_table: Der Name der Zieltabelle in der Datenbank.
        prozedur: Der Name der prozedur, die nach dem Import ausgeführt werden soll.
        create_table_query: SQL-Text zum Erstellen der temporären tabelle.
            Der Text kann ``{table_name}`` als Platzhalter für ``target_table`` enthalten.
        database: Der Name der Datenbank, in die die Daten importiert werden sollen.
        db_credentials: Optionale direkte DB-Zugangsdaten.

    Returns:
        True bei Erfolg, False bei Fehler.
    """

    temp_table = f"{target_table}_temp"
    safe_temp_table = _validate_identifier(temp_table)
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        cursor = connection.cursor()
        # Temporäre tabelle erstellen
        cursor.execute(create_table_query.format(table_name=target_table))
        connection.commit()
        # Überprüfen, ob die temporäre tabelle erstellt wurde
        cursor.execute(f"SHOW COLUMNS FROM {safe_temp_table};")
        # Hole die Spaltennamen der temporären tabelle
        table_columns = [row[0] for row in cursor.fetchall()]
        df = pd.read_csv(csv_file_path, dtype=str)
        if df.empty:
            logger.info(f"CSV-datei enthält keine Daten (nur Überschriften), Import wird übersprungen: {csv_file_path}")
            return True
        column_mapping = get_column_mapping(database, db_credentials=db_credentials)

        df.rename(columns=column_mapping, inplace=True)
        df = df.where(pd.notnull(df), None)
        df = df[[col for col in df.columns if col in table_columns]]

        if df.empty:
            raise ValueError("Keine passenden Daten in der CSV-datei nach Spaltenabgleich!")

        df = df.astype(str)
        connection.autocommit = False  # Deaktiviere das automatische Committen
        with connection.cursor() as cursor:
            try:
                batch_insert(cursor, df, temp_table, [], "Nein")
                connection.commit()
            except Exception as e:
                logger.error(f"Fehler beim Batch-Insert in temporäre tabelle: {e}", exc_info=True)
                _safe_rollback(connection)
                raise

            try:
                cursor.callproc(prozedur)
                connection.commit()
                logger.info(f"{prozedur} erfolgreich ausgeführt")
            except Exception as e:
                logger.error(f"Fehler bei der Ausführung der prozedur: {e}", exc_info=True)
                _safe_rollback(connection)
                raise

            cursor.execute(f"DROP TEMPORARY TABLE IF EXISTS {safe_temp_table};")
            connection.commit()

        logger.info(f"Import mit temporärer tabelle für {target_table} erfolgreich abgeschlossen")
        return True

    except Exception as e:
        logger.error(f"Fehler beim Einfügen der Daten in {target_table}: {e}", exc_info=True)
        raise
    finally:
        connection.close()


def rechnungsemail(csv_file_path: str, database: str = DATABASE, db_credentials: DbCredentials | None = None) -> bool:
    """Importiert die Rechnungsemail aus einer CSV-datei in die Datenbank.

    Extrahiert aus dem Support Log die geänderten Rechnungsemail-Adressen
    und importiert diese in die tabelle tb_rechnungsemail.

    Args:
        csv_file_path: Der Pfad zur CSV-datei, die importiert werden soll.
        database: Der Name der Datenbank, in die die Daten importiert werden sollen.
        db_credentials: Optionale direkte DB-Zugangsdaten.

    Returns:
        True bei Erfolg, False bei Fehler.
    """

    df = pd.read_csv(csv_file_path, dtype=str)
    target_table = "tb_rechnungsemail"
    email_pattern = r"""Account Parameter 'Rechnungsemail' value changed from '([^']*)' to '-'"""
    CreatedbyUser_pattern = r"Aschendorff"

    def extract_email(text: object) -> str | None:
        """Extrahiert die vorherige Rechnungsemail-Adresse aus einem Logtext."""
        match = re.search(email_pattern, str(text))
        if match is None:
            return None
        return match.group(1)

    df["Rechnungsemail"] = df["Support Log Notes"].apply(extract_email)
    # Filter: Rechnungsemail vorhanden UND Created by User entspricht Muster
    df_with_email = df[
        df["Rechnungsemail"].notna()
        & (df["Rechnungsemail"] != "leer")
        & df["Created by User"].astype(str).str.contains(CreatedbyUser_pattern)
    ]

    df_with_email = df_with_email.rename(columns={"eSuite Account": "ACCOUNTID", "Rechnungsemail": "RECHNUNGSEMAIL"})
    select_cols = ["ACCOUNTID", "RECHNUNGSEMAIL", "Support Log Notes"]
    if "Support Log Date" in df_with_email.columns:
        select_cols.append("Support Log Date")
    df_output = df_with_email[select_cols].copy()

    if "Support Log Date" in df_output.columns:
        df_output = df_output.sort_values(by=["ACCOUNTID", "Support Log Date"], ascending=[True, False])

    df_output = df_output.drop_duplicates(subset=["ACCOUNTID"], keep="first")
    df_output_imp = df_output[["ACCOUNTID", "RECHNUNGSEMAIL"]]

    connection = None
    connection = connect_to_db(database, credentials=db_credentials)
    try:
        if df_output_imp.empty:
            logger.info(f"Keine Daten zum Importieren gefunden in {csv_file_path}.")
            return True  # No data to import is not an error condition

        connection.autocommit = False
        with connection.cursor() as cursor:
            excluded_fields = get_update_exclusion_fields(
                target_table, database, db_credentials=db_credentials
            )  # Ruft die Felder ab, die von der Aktualisierung ausgeschlossen sind

            batch_insert(cursor, df_output_imp, target_table, excluded_fields, "Nein")
            connection.commit()

        logger.info("Rechnungsemail Import erfolgreich abgeschlossen")
        return True

    except Exception as e:
        _safe_rollback(connection)
        logger.error(f"Fehler beim Einfügen der Daten in {target_table}: {e}", exc_info=True)
        raise
    finally:
        if connection:
            connection.close()


def ivw(db_credentials: DbCredentials | None = None) -> bool:
    """Bereinigt die IVW-Daten in der tabelle tb_ivw_grundlage.

    Prüft ob die maximalen Periodstart-Daten für Print und ePaper
    übereinstimmen und der letzte Import vor heute liegt. Wenn ja,
    wird die Stored Procedure 'Bereinigung_tb_ivw_grundlage' ausgeführt.

    Returns:
        True bei erfolgreicher Bereinigung, False wenn Bedingungen nicht erfüllt oder bei Fehler.
    """
    logger.info("Starte IVW-Bereinigung...")
    # Wenn Periodstart für Print und ePaper gleich ist, führe prozedur "Bereinigung_tb_ivw_grundlage" aus
    Max_date_ivw_print_sql = """SELECT MAX(Periodstart) FROM tb_ivw_grundlage WHERE Art = 'Print'"""
    Max_date_ivw_epaper_sql = """SELECT MAX(Periodstart) FROM tb_ivw_grundlage WHERE Art = 'epaper' """

    Max_date_ivw_print = execute_dataframe_query(Max_date_ivw_print_sql, db_credentials=db_credentials).iloc[0, 0]
    Max_date_ivw_epaper = execute_dataframe_query(Max_date_ivw_epaper_sql, db_credentials=db_credentials).iloc[0, 0]

    pruef_ivw = execute_dataframe_query(
        """SELECT Date(Last_import) FROM tb_bewegungsdaten WHERE report = 'IVW'""", db_credentials=db_credentials
    )
    pruef_ivw_date = None
    if not pruef_ivw.empty:
        pruef_ivw_date = pd.to_datetime(pruef_ivw.iloc[0, 0]).date()

    if (
        Max_date_ivw_print == Max_date_ivw_epaper
        and pruef_ivw_date is not None
        and pruef_ivw_date < datetime.now(TIMEZONE).date()
    ):
        connection = None
        try:
            connection = connect_to_db(credentials=db_credentials)
            with connection.cursor() as cursor:
                cursor.callproc("Bereinigung_tb_ivw_grundlage")
                connection.commit()
            update_last_updated(
                "IVW", datetime.now(TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"), db_credentials=db_credentials
            )
            logger.info("IVW-Bereinigung erfolgreich abgeschlossen")
            return True
        except Exception as e:
            logger.error(f"Fehler bei der Bereinigung der IVW-Daten: {e}", exc_info=True)
            raise
        finally:
            if connection:
                connection.close()
    else:
        logger.info("Bedingungen für Bereinigung nicht erfüllt.")
        return False


def post_subscriptions() -> None:
    """Führt die Nachverarbeitung nach dem Import des SubscriptionsReports durch.

    Synchronisiert Subscription-Referenzen in eSuite, aktualisiert die
    verkürzte Subscription-tabelle und bereinigt Subscriptions.
    """
    from ..api.esuite_cleanup import subscriptionbereinigung
    from ..api.esuite_sync import update_subscription_references

    update_subscription_references()
    prozedur_db("Update_tb_sub_shortened")
    refresh_entitlement_update_table()
    subscriptionbereinigung()


def refresh_entitlement_update_table() -> bool:
    """Aktualisiert die Entitlement-Arbeitsliste nach dem Subscription-Import."""
    query = get_query_text("ENTITLEMENT_UPDATE_REFRESH")
    try:
        result = execute_sql_query(query)
    except Exception as e:
        logger.exception(f"Error refreshing entitlement update table: {e}")
        return False

    if result is not True:
        return False

    return mark_expired_entitlement_updates_processed()


def mark_expired_entitlement_updates_processed() -> bool:
    """Markiert abgelaufene Entitlement-Updates automatisch als bearbeitet."""
    query = """
    UPDATE dbm_lesermarkt.tb_entitlement_update
    SET bearbeitet = 1
    WHERE bearbeitet = 0
    AND date(enddate) < curdate()
    """
    try:
        result = execute_sql_query(query)
    except Exception as e:
        logger.exception(f"Error marking expired entitlement updates as processed: {e}")
        return False

    return result is True


def post_accountreport() -> None:
    """Führt die Nachverarbeitung nach dem Import des AccountReports durch.

    Synchronisiert Account-Referenzen in eSuite.
    """
    from ..api.esuite_sync import update_account_reference

    update_account_reference()


def post_orderreport(db_credentials: DbCredentials | None = None) -> None:
    """Führt die Nachverarbeitung nach dem Import des OrderReports durch.

    Führt den Workaround für REFUND_REASON_REFUNDS aus.
    """
    prozedur_db("Workaround_REFUND_REASON_REFUNDS", db_credentials=db_credentials)


def import_customersupportlog(filepath: str, db_credentials: DbCredentials | None = None) -> bool:
    """Importiert den CustomerSupportLog und verarbeitet Rechnungsemails.

    Args:
        filepath: Pfad zur CSV-datei.

    Returns:
        True wenn alle Schritte erfolgreich waren.

    Raises:
        Exception: Bei Fehlern in Rechnungsemail-Verarbeitung oder Timestamp-Update.
    """
    if not handle_import(import_table, filepath, "tb_customer_suppot_log", "Nein", db_credentials=db_credentials):
        raise RuntimeError(f"Import von Customer Support Log fehlgeschlagen: {filepath}")
    rechnungsemail(filepath, db_credentials=db_credentials)
    update_last_updated(
        "RECHNUNGSEMAIL", datetime.now(TIMEZONE).strftime("%Y-%m-%d %H:%M:%S"), db_credentials=db_credentials
    )
    return True


def save_df_to_db(
    df: pd.DataFrame,
    table_name: str,
    truncate_table: str = "Ja",
    database: str = "dbm_lesermarkt",
    db_credentials: DbCredentials | None = None,
) -> bool:
    """Speichert einen DataFrame per batch_insert in die angegebene tabelle.

    Args:
        df: Der zu speichernde DataFrame.
        table_name: Name der Zieltabelle.
        truncate_table: Ob die tabelle vorher geleert werden soll.
        database: Name der Datenbank.
        db_credentials: Optionale direkte DB-Zugangsdaten.
    Returns:
        bool: True bei Erfolg, False bei Fehler
    """
    connection = None
    try:
        connection = connect_to_db(database, credentials=db_credentials)

        column_mapping = get_column_mapping(database, db_credentials=db_credentials)
        df = df.rename(columns=column_mapping)
        df = df.replace("", None)
        df = df.where(pd.notnull(df), None)

        if df.empty:
            logger.info("Keine Daten zum Importieren gefunden.")
            return True

        connection.autocommit = False
        with connection.cursor() as cursor:
            excluded_fields = get_update_exclusion_fields(table_name, database, db_credentials=db_credentials)
            batch_insert(cursor, df, table_name, excluded_fields, truncate_table)
            connection.commit()

        logger.info(f"{len(df)} Datensätze in {table_name} eingefügt.")
        return True

    except Exception as e:
        _safe_rollback(connection)
        logger.error(f"Fehler beim Einfügen in {table_name}: {e}", exc_info=True)
        raise
    finally:
        if connection:
            connection.close()
